export function ReportsView({ ctx }: {
    ctx: Ctx;
}) { const state = useData('admin/reports', ctx.revision), data = state.data; return <><Heading title="דוחות וביצועים" description="נתוני הזמנות ופרסום מתוך הפעילות האמיתית במערכת." actions={<Button variant="outline" onClick={() => exportSpreadsheet('postflow-reports.xlsx', [['חודש', 'הזמנות', 'תשלומים בש״ח'], ...(data?.byMonth || []).map((r: Row) => [r.month, r.count, r.total / 100])])}><Download size={15}/>הורדת דוח</Button>}/><Loading state={state}>{data && <><Stats items={[{ label: 'תקבולים מאומתים', value: money(data.totals.revenue), sub: 'ללא הזמנות שבוטלו', icon: <Wallet size={17}/> }, { label: 'הזמנות', value: data.totals.count, sub: 'כל ההזמנות במערכת', icon: <ShoppingCart size={17}/> }, { label: 'ממתינות לתשלום', value: data.totals.pending || 0, sub: 'נדרש אימות תקבול', icon: <Clock size={17}/> }, { label: 'לקוחות רשומים', value: data.customers.n, sub: 'חשבונות שהתחברו למערכת', icon: <Users size={17}/> }]}/><div className="connection-grid"><div className="panel"><h3 className="mb-6">מצב הכתבות</h3>{data.statuses.length ? <div className="report-bars">{data.statuses.map((r: Row) => <div key={r.status}><div className="flex-row spaced text-sm"><span>{stages[r.status] || r.status}</span><b>{r.count}</b></div><div className="report-bar"><div style={{ width: (r.count / Math.max(...data.statuses.map((r: Row) => r.count)) * 100) + '%' }}/></div></div>)}</div> : <Empty title="נתוני הכתבות יופיעו כאן"/>}</div><div className="panel"><h3 className="mb-6">האתרים עם הכי הרבה הזמנות</h3>{data.bySite.length ? <div className="report-bars">{data.bySite.map((r: Row) => <div key={r.name}><div className="flex-row spaced text-sm"><span>{r.name}</span><b>{r.count} כתבות</b></div><div className="report-bar"><div style={{ width: (r.count / Math.max(...data.bySite.map((r: Row) => r.count)) * 100) + '%' }}/></div></div>)}</div> : <Empty title="האתרים המובילים יופיעו עם תחילת הפעילות"/>}</div></div><div className="panel"><h3 className="mb-5">תשלומים לפי חודש</h3><DataTable headers={['חודש', 'הזמנות ששולמו', 'סכום כולל']} rows={data.byMonth.map((x: Row) => ({ ...x, id: x.month }))} emptyTitle="עדיין אין תשלומים מאומתים" render={r => <><TableCell>{r.month}</TableCell><TableCell>{r.count}</TableCell><TableCell>{money(r.total)}</TableCell></>}/></div></>}</Loading></>; }
export function LogsView({ ctx, jobs = false }: {
    ctx: Ctx;
    jobs?: boolean;
}) { const state = useData('admin/' + (jobs ? 'jobs' : 'activity'), ctx.revision), rows = state.data?.[jobs ? 'jobs' : 'activity'] || []; return <><Heading title={jobs ? 'יומן חיבורים' : 'יומן פעילות'} description={jobs ? 'בקשות AI, פרסום והודעות. הצלחה תסומן רק לאחר אישור הספק.' : 'תיעוד הפעולות החשובות — מי ביצע, מה השתנה ומתי.'} actions={<Button variant="outline" onClick={ctx.refresh}><RefreshCw size={15}/>רענון</Button>}/><Loading state={state}><DataTable headers={jobs ? ['פעולה', 'סטטוס', 'תאריך', 'פרטים', 'טיפול'] : ['פעולה', 'מבצע', 'תאריך', 'פרטים']} rows={rows} emptyTitle="היומן נקי" emptyText="הפעולות החדשות יירשמו כאן באופן אוטומטי." render={r => jobs ? <><TableCell className="row-title">{r.kind}</TableCell><TableCell><Badge status={r.status}/></TableCell><TableCell>{when(r.created)}</TableCell><TableCell><div className="max-w-[300px] break-all whitespace-normal text-xs">{r.error || r.title || r.article_id || r.order_id || 'אירוע מערכת'}</div></TableCell><TableCell>{r.status === 'requested' && <Button variant="outline" size="sm" onClick={() => ctx.open({ title: 'שליחת אירוע לספק', description: 'הפעולה תשלח את נתוני האירוע דרך החיבור שהוגדר.', render: (close: () => void) => <DispatchForm ctx={ctx} id={r.id} close={close}/> })}><Send size={13}/>שליחה</Button>}{r.kind === 'ai_generation' && r.content && <Button variant="ghost" size="sm" onClick={() => download('ai-result.txt', r.title + '\n\n' + r.content)}><Download size={13}/>תוצר AI</Button>}</TableCell></> : <><TableCell className="row-title">{r.action}</TableCell><TableCell>{r.actor}</TableCell><TableCell>{when(r.created)}</TableCell><TableCell className="whitespace-normal max-w-[400px]"><code className="text-[11px] text-muted-foreground">{r.data}</code></TableCell></>}/></Loading></>; }
function DispatchForm({ ctx, id, close }: {
    ctx: Ctx;
    id: string;
    close: () => void;
}) { const [channel, setChannel] = useState('email'); return <div className="stack"><Pick value={channel} onChange={setChannel} options={{ email: 'דוא״ל', whatsapp: 'WhatsApp', payments: 'סליקה' }}/><Button onClick={() => ctx.run(() => api('admin/jobs/' + id + '/dispatch', 'POST', { channel }), 'הספק אישר קבלת האירוע').then(close).catch(() => { })}>שליחת האירוע</Button></div>; }
export function ApiView({ ctx }: {
    ctx: Ctx;
}) { const state = useData('api-keys', ctx.revision); return <><Heading title="חיבור API" description="חיבור המערכת לכלי הסוכנות שלכם, עם מפתח נפרד לכל חיבור." actions={<Button onClick={() => ctx.open({ title: 'יצירת מפתח API', description: 'המפתח יוצג פעם אחת. יש לשמור אותו אצלכם.', render: (close: () => void) => <ActionForm fields={[['name', 'שם החיבור', 'text']]} submit={async (b) => { const result = await api('api-keys', 'POST', b); ctx.refresh(); ctx.open({ title: 'המפתח שלכם', description: 'המפתח מאפשר גישה לנתוני החשבון. שמרו אותו בצורה מאובטחת.', render: () => <div className="stack"><div className="code-block">{result.key}</div><Button onClick={() => navigator.clipboard.writeText(result.key).then(() => toast.success('הועתק'))}><Copy size={15}/>העתקת המפתח</Button></div> }); }} label="יצירת מפתח"/> })}><Plus size={15}/>מפתח חדש</Button>}/><div className="panel"><h3 className="mb-5">מפתחות פעילים</h3><Loading state={state}><DataTable headers={['שם חיבור', 'תוקף', 'סטטוס', '']} rows={state.data?.keys || []} emptyTitle="אין עדיין מפתחות" emptyText="צרו מפתח כדי לעבוד מול המערכת מכלי חיצוני." render={k => <><TableCell className="row-title">{k.resource}</TableCell><TableCell>{when(k.expires)}</TableCell><TableCell><Badge tone={k.used ? 'red' : 'green'}>{k.used ? 'בוטל' : 'פעיל'}</Badge></TableCell><TableCell><Button variant="ghost" size="sm" disabled={!!k.used} onClick={() => ctx.run(() => api('api-keys/' + k.id, 'DELETE'), 'המפתח בוטל').catch(() => { })}>ביטול מפתח</Button></TableCell></>}/></Loading></div><div className="panel"><h3 className="mb-3">תחילת עבודה</h3><p className="muted mb-4">הבקשות נשלחות עם Authorization: Bearer. באתר פרטי נדרשת גם הרשאת השירות של האירוח. המפתח מוגבל לחשבון ולנתונים שלכם.</p><pre className="code-block">{`GET /api/v1/pricelist\nGET /api/v1/orders\nGET /api/v1/articles\n\nAuthorization: Bearer pf_YOUR_API_KEY\n\nPOST /api/v1/cart\n{\n  "website_id": "SITE_ID",\n  "topic": "נושא הכתבה",\n  "words": 500,\n  "quantity": 1\n}\n\nPOST /api/v1/quote\n{ "coupon": "" }\n\nPOST /api/v1/checkout\n{\n  "name": "שם המזמין",\n  "phone": "0500000000",\n  "payment": "invoice",\n  "accepted": true,\n  "idempotency": "unique-request-uuid",\n  "expected_total": 5900,\n  "pricing_token": "TOKEN_FROM_QUOTE"\n}`}</pre><p className="muted mt-4">כל הסכומים ב־API הם באגורות. expected_total ו-pricing_token חייבים להגיע מאותה תשובת quote. שינוי מחירים דורש quote חדש ואישור חוזר. בקשה חוזרת עם אותו idempotency מחזירה את אותה הזמנה.</p></div></>; }
export { default as ProfileView } from './account-settings';
export { default as BulkView } from './bulk-order-view';
export function SupplierView({ token }: {
    token: string;
}) { const state = useData('supplier/' + token), [url, setUrl] = useState(''), [done, setDone] = useState(false), [error, setError] = useState(''); return <div className="main max-w-3xl py-12"><BrandLogo className="brand-logo-desktop mb-6"/><Heading title="הגשת קישור לפרסום" description="הקישור מיועד לספק המטפל בכתבה."/>{done ? <div className="panel"><Empty icon={CheckCircle2} title="קישור הפרסום התקבל" text="הלקוח יוכל לראות את הכתבה בארכיון הפרסומים שלו."/></div> : <Loading state={state}>{state.data && <div className="panel"><Badge tone="green">{state.data.article.website_name}</Badge><h2 className="my-5">{state.data.article.title}</h2>{state.data.article.image&&<img src={'/api/supplier/'+token+'?asset=image'} alt="תמונת הכתבה" className="rounded-lg max-h-64 object-contain mb-5"/>}<p className="muted">{state.data.article.image_credit}</p>{state.data.article.secondary_image&&<figure><img src={'/api/supplier/'+token+'?asset=image&secondary=1'} alt="תמונה משנית" className="max-h-64 object-contain"/><figcaption className="text-xs">{state.data.article.secondary_image_credit}</figcaption></figure>}{state.data.article.meta_description&&<section dir="rtl" className="panel mb-4"><h3>תיאור קצר / תיאור מטא</h3><p className="whitespace-pre-wrap">{state.data.article.meta_description}</p></section>}{state.data.article.client_notes&&<section dir="rtl" className="panel mb-4"><h3>הערות לפרסום</h3><p className="whitespace-pre-wrap">{state.data.article.client_notes}</p></section>}<div className="article-preview rich-body mb-5" dangerouslySetInnerHTML={{__html:state.data.article.content}}/><a className="text-primary block mb-4" href={'/api/supplier/'+token+'?asset=word'}>הורדת Word עם התמונות והקרדיטים</a>{state.data.article.document&&<a href={'/api/supplier/'+token+'?asset=document'} className="text-primary text-sm mb-5 block">הורדת מסמך הכתבה</a>}{state.data.article.cancel_pending&&<p className="account-warning">התקבלה בקשת ביטול. יש לעצור טיפול ולתאם עם המנהל לפני פרסום.</p>}<Field label="כתובת הכתבה שפורסמה"><Input type="url" dir="ltr" value={url} onChange={e => setUrl(e.target.value)} placeholder="https://"/></Field><ErrorBox error={error}/><Button className="mt-5" disabled={!url||state.data.article.cancel_pending} onClick={async () => { try {
    await api('supplier/' + token, 'POST', { url });
    setDone(true);
}
catch (e) {
    setError((e as Error).message);
} }}><Send size={15}/>הגשת קישור</Button></div>}</Loading>}</div>; }
export function ImageSearch({ onSelected }: {
    onSelected: (file: Row) => void;
}) { const [query, setQuery] = useState(''), [photos, setPhotos] = useState<Row[]>([]), [busy, setBusy] = useState(false), [error, setError] = useState(''); return <div className="stack"><div className="flex-row"><Input value={query} onChange={e => setQuery(e.target.value)} placeholder="נושא התמונה, רצוי באנגלית"/><Button disabled={busy || !query} onClick={async () => { setBusy(true); setError(''); try {
    const result = await api('image-search?query=' + encodeURIComponent(query));
    setPhotos(result.photos);
}
catch (e) {
    setError((e as Error).message);
}
finally {
    setBusy(false);
} }}>חיפוש</Button></div><ErrorBox error={error}/><div className="grid grid-cols-2 gap-3">{photos.map(p => <div key={p.id}><button disabled={busy} onClick={async () => { setBusy(true); try {
    const result = await api('image-import', 'POST', { photo_id: p.id });
    onSelected(result);
}
catch (e) {
    setError((e as Error).message);
}
finally {
    setBusy(false);
} }} className="block w-full"><img className="rounded-lg h-28 w-full object-cover" src={p.src} alt="תמונת מאגר"/></button><a href={p.url} target="_blank" rel="noreferrer" className="text-[10px] text-muted-foreground">צילום: {p.photographer} / Pexels</a></div>)}</div><a href="https://www.pexels.com" target="_blank" rel="noreferrer" className="text-primary text-xs">תמונות באדיבות Pexels</a></div>; }
